    if (!this.scrollLock) {
      // Entering scroll lock — save current transform state
      this._savedPanX = this.panX
      this._savedPanY = this.panY
      this._savedScale = this.scale
      // Reset transform so canvas-world is at origin; scrolling replaces panning
      this.scale = 1.0
      this.panX = 0
      this.panY = 0
      this.scrollLock = true
      this.element.classList.add("scroll-locked")
      this.updateTransform()
      this._updateWorldSize()
      // Convert saved pan offset into scroll position (pan is negative when scrolled right/down)
      this.element.scrollLeft = -this._savedPanX / this._savedScale
      this.element.scrollTop = -this._savedPanY / this._savedScale
    } else {
      // Leaving scroll lock — convert current scroll position back to pan offset
      const scrollX = this.element.scrollLeft
      const scrollY = this.element.scrollTop
      const restoreScale = this._savedScale ?? 1.0
      this.panX = -scrollX * restoreScale
      this.panY = -scrollY * restoreScale
      this.scale = restoreScale
      this.scrollLock = false
      this.element.classList.remove("scroll-locked")
      this.element.scrollLeft = 0
      this.element.scrollTop = 0
      this.updateTransform()
      this._updateWorldSize()
    }
    this.updateZoomIndicator()
  }"}

